const edition = globalThis.makeSubjectEdition({"year":2016,"grade":"5-6","tasksFile":"5-6_1.pdf","answersFile":"reviewed-5-6-v1.pdf","title":"XVII век. Россия накануне перемен","variant":"1","variantLabel":"Вариант 1","subject":"golden-fleece","contest":"Золотое руно","letters":"ABCD","count":60,"language":"ru","points":3,"sourceFile":"sources/golden-fleece/2016/5-6-v1.json","editionSuffix":"v1","editionLabel":"Вариант 1","sections":[{"start":1,"title":"Московская держава"},{"start":16,"title":"На просторах московского царства"},{"start":31,"title":"В избах, теремах, храмах"},{"start":41,"title":"Вертоград многоцветный"},{"start":51,"title":"Русский стиль"}],"reviewedKey":true}, [{"title":"Родство будущего царя","question":"Какое родство связывало Михаила Романова с царём Фёдором Иоанновичем?","choices":["Он был родным братом царя","Он был двоюродным братом царя","Он был родным племянником царя","Он был двоюродным племянником царя"],"answer":3,"steps":["Отец Михаила, Фёдор Никитич Романов, приходился двоюродным братом царю Фёдору Иоанновичу. Мать царя Анастасия Романовна была сестрой деда Михаила.","Поэтому Михаил был двоюродным племянником Фёдора Иоанновича. Родство с прежней династией было одним из доводов в пользу его избрания в 1613 году."],"references":["https://bigenc.ru/l/russkie-tsari-i-tsaritsy-f87477"],"taskUrl":"https://runodog.ru/ZR_1516/5-6_1.pdf#page=1","adaptation":"Редакция вопроса проверена по первоисточникам."},{"title":"Семья Марселисов","question":"Род Марселисов был известен в России как семья …","choices":["военных","архитекторов","купцов и заводчиков","врачей"],"answer":2,"steps":["Марселисы торговали и брали в управление металлургические заводы.","Их предприятия выпускали железные изделия, в том числе для государства."]},{"title":"Конец Смуты","question":"С этим событием историки связывают окончание Смутного времени.","choices":["Начало русско-польской войны","Установление «Семибоярщины»","Восстание И. Болотникова","Воцарение Михаила Романова"],"answer":3,"steps":["После освобождения Москвы Земский собор собрался для выборов государя.","Воцарение Михаила Романова в 1613 году восстановило признанную династию."]},{"title":"Советник молодого царя","question":"В первые годы царствования Алексея Михайловича самым влиятельным человеком в государстве был …","choices":["Л. Плещеев","В. Голицын","Б. Морозов","Д. Пожарский"],"answer":2,"steps":["Борис Морозов воспитывал Алексея Михайловича, а после его воцарения управлял несколькими приказами.","Это дало ему большое влияние на внутреннюю политику."]},{"title":"Первый патриарх","question":"Первым московским патриархом был …","choices":["Иов","Филарет","Гермоген","Никон"],"answer":0,"steps":["До учреждения патриаршества главой русской церкви был митрополит.","В 1589 году московский митрополит Иов стал первым патриархом."]},{"title":"Государственные крестьяне","question":"Крестьяне, находившиеся в прямой зависимости от государства, назывались …","choices":["дворцовыми","монастырскими","частновладельческими","черносошными"],"answer":3,"steps":["Черносошные крестьяне жили на государственных землях и платили подати казне.","Они не принадлежали частному помещику."]},{"title":"Возвращение Смоленска","question":"В 1667 году Смоленск вернулся в состав России по условиям …","choices":["Нерчинского мира","Андрусовского перемирия","Кардисского мира","Поляновского мира"],"answer":1,"steps":["Андрусовское перемирие 1667 года приостановило войну России с Речью Посполитой.","Смоленск по условиям соглашения закрепили за Россией."]},{"title":"Потерянный выход к морю","question":"Согласно условиям Столбовского мира 1617 года, Россия лишилась выхода к этому морю.","choices":["Балтийское","Черное","Белое","Каспийское"],"answer":0,"steps":["Договор позволил вернуть Новгород, но Швеция сохранила земли у Финского залива.","Поэтому выход к Балтийскому морю оказался закрыт."]},{"title":"Кто правил после мятежа","question":"После стрелецкого мятежа 1682 года фактическое управление страной перешло к …","choices":["царевне Софье","Ивану V","Петру I","Петру I и Ивану V"],"answer":0,"steps":["В 1682 году царями стали Иван и Пётр.","Поскольку братья были молоды, управление сосредоточилось у их старшей сестры Софьи."]},{"title":"Решение гетмана","question":"Решение о переходе Украины в подданство России в 1654 году было принято по инициативе гетмана …","choices":["И. Выговского","П. Дорошенко","Б. Хмельницкого","И. Мазепы"],"answer":2,"steps":["Богдан Хмельницкий искал поддержки в войне с Речью Посполитой.","В 1654 году на Переяславской раде была принята присяга царю Алексею Михайловичу."]},{"title":"Долгая жизнь свода","question":"Соборное Уложение 1649 года считалось действующим законодательным актом до царствования …","choices":["Николая I","Елизаветы I","Александра I","Екатерины II"],"answer":0,"steps":["Соборное уложение оставалось важной основой законодательства почти два века.","При Николае I свод законов подготовили и ввели в действие под руководством Михаила Сперанского."]},{"title":"Чигиринские походы","question":"С какой державой воевало Русское государство во время Чигиринских походов 1677 и 1678 годов?","choices":["С Османской империей (Турцией)","С Китаем","С Польшей","Со Швецией"],"answer":0,"steps":["Османское войско дважды осаждало Чигирин, в 1677 и 1678 годах. Город обороняли русские и казацкие силы.","Чигиринские походы относятся к войне с Османской империей, которую также называли Турцией."],"references":["https://bigenc.ru/l/istoriia-rechi-pospolitoi-a76574","https://bigenc.ru/b/pervaia-russko-turetskaia-sem-f998d7"],"taskUrl":"https://runodog.ru/ZR_1516/5-6_1.pdf#page=1","adaptation":"Редакция вопроса проверена по первоисточникам."},{"title":"Срок для Киева","question":"По Андрусовскому перемирию 1667 года, Киев …","choices":["навечно переходил к России","отходил к России на время перемирия","оставался в составе Польши","на два года переходил к России"],"answer":3,"steps":["Андрусовское перемирие передавало Киев России на два года.","Позднее «Вечный мир» закрепил его за Россией без этого ограничения."]},{"title":"Ополчение из Нижнего","question":"В Смутное время жители Нижнего Новгорода сыграли важнейшую роль в …","choices":["победе над В. Шуйским","формировании Первого ополчения","разгроме И. Болотникова","формировании Второго ополчения"],"answer":3,"steps":["Минин призвал нижегородцев собрать средства и найти военного руководителя.","Так сформировалось Второе ополчение во главе с Пожарским."]},{"title":"Защитник Смоленска","question":"Оборону Смоленска в 1609-1611 годах возглавлял …","choices":["Д. Шуйский","М. Скопин-Шуйский","М. Шеин","А. Ордин-Нащокин"],"answer":2,"steps":["Обороной Смоленска во время осады руководил воевода Михаил Шеин.","Город сопротивлялся с 1609 по 1611 год."]},{"title":"Управление уездом","question":"Во главе уездов в XVII веке стояли …","choices":["губернаторы","окольничие","городничие","воеводы"],"answer":3,"steps":["Воевод назначали из Москвы для управления городом и уездом.","Они ведали военными, административными и судебными делами."]},{"title":"Путь к Амуру","question":"Первым русским землепроходцем, достигшим Амура, был …","choices":["В. Поярков","Е. Хабаров","И. Москвитин","С. Дежнев"],"answer":0,"steps":["Экспедиция Василия Пояркова отправилась из Якутска и вышла к Амуру.","Позднее этот край исследовал и Ерофей Хабаров."]},{"title":"Два старейших полка","question":"Эти полки, старейшие в русской армии, ведут свою историю из потешных, образованных в конце XVII века.","choices":["Измайловский и Волынский","Стрелецкий и Артиллерийский","Бутырский и Лефортовский","Семеновский и Преображенский"],"answer":3,"steps":["Преображенский и Семёновский полки выросли из учебных отрядов юного Петра.","Их имена напоминают о подмосковных сёлах, где проходили занятия."]},{"title":"Доходы от Сибири","question":"В XVII веке Сибирь обогащала русскую казну преимущественно …","choices":["железом","мехами","медью","серебром"],"answer":1,"steps":["Сибирские меха стоили дорого и поступали в казну в виде ясака.","Особенно ценили пушнину соболя."]},{"title":"Первые поселения","question":"Первые населенные пункты, основанные русскими в Сибири, как правило, назывались …","choices":["слободами","деревнями","острогами","посадами"],"answer":2,"steps":["Острогом называли укреплённое поселение с деревянным частоколом.","Такие пункты служили опорой для движения по рекам и освоения новых земель."]},{"title":"Городские жители","question":"Так в XVII веке называлось городское торгово-ремесленное население России.","choices":["Вольные люди","Посадские люди","Слободские люди","Крестьяне"],"answer":1,"steps":["Посад лежал за пределами укреплённого центра города.","Его торговцы и ремесленники образовывали особую группу посадских людей."]},{"title":"Соколиная охота","question":"Этот русский царь написал подробное руководство по соколиной охоте.","choices":["Борис Годунов","Лжедмитрий I","Алексей Михайлович","Петр I"],"answer":2,"steps":["Алексей Михайлович держал обученных ловчих птиц и устраивал выезды.","Придворные обряды охоты он описал в «Уряднике сокольничья пути»."]},{"title":"Кочевники у Волги","question":"Этот кочевой народ в XVII веке начал селиться в европейской части России.","choices":["Маньчжуры","Казахи","Калмыки","Ногаи"],"answer":2,"steps":["В XVII веке калмыцкие кочевья переместились к низовьям Волги.","Там возникло Калмыцкое ханство."]},{"title":"Правило казаков","question":"Принцип «С Дона выдачи нет!» означал, что казаки не выдавали …","choices":["военнопленных","захваченных богатств","военных тайн","беглых крепостных"],"answer":3,"steps":["Крепостные, бежавшие от владельцев на Дон, могли войти в казачье сообщество.","Обычай запрещал выдавать беглецов тем, кто требовал их возвращения."]},{"title":"Смысл слова «тягло»","question":"«Тяглом» в России XVII века называли …","choices":["орудие наказания","средство передвижения","орудие труда","совокупность налогов и повинностей"],"answer":3,"steps":["Государство возлагало на податных жителей денежные платежи и обязанности.","Все эти повинности вместе называли тяглом."]},{"title":"Казачье собрание","question":"Высший орган казачьего самоуправления на Дону в XVII веке – …","choices":["Рада","Собрание","Коло","Круг"],"answer":3,"steps":["Казаки собирались на круг, чтобы обсудить дела войска и выбрать атамана.","Решения принимало собрание, а не один назначенный начальник."]},{"title":"Почтовые пути","question":"Международные почтовые линии появились в России при царе …","choices":["Федоре Алексеевиче","Михаиле Федоровиче","Алексее Михайловиче","Борисе Годунове"],"answer":2,"steps":["При Алексее Михайловиче устроили постоянное почтовое сообщение через западную границу.","Афанасий Ордин-Нащокин участвовал в создании связи с Вильно и Ригой."]},{"title":"Письмо царя","question":"Узнав о бегстве В. Ордина-Нащокина в Польшу, царь Алексей Михайлович …","choices":["приговорил его к смерти","послал его отцу утешающее письмо","отправил его отца в отставку","отправил его семью в ссылку"],"answer":1,"steps":["Сын дипломата Ордина-Нащокина бежал за границу, что могло вызвать подозрения к отцу.","Алексей Михайлович поддержал отца письмом."]},{"title":"Управление врачами","question":"С 1620 года медициной и медиками было указано руководить …","choices":["Медицинской канцелярии","Медицинской коллегии","Аптекарской палате","Аптекарскому приказу"],"answer":3,"steps":["Аптекарский приказ ведал закупкой лекарств и работой лекарей.","Позднее при нём появилась школа для подготовки специалистов."]},{"title":"Почему росла цена пищи","question":"Введенный в 1646 году налог на соль «ударил» по простому народу, потому что в его питании важное место …","choices":["занимало сало","занимала соленая рыба","занимала солонина","занимали соленые овощи"],"answer":1,"steps":["Соль была нужна для заготовки и хранения рыбы.","Из-за налога дорожало блюдо, которое часто ели небогатые люди."]},{"title":"Дворец в Коломенском","question":"Этот дворец, построенный при Алексее Михайловиче, был разобран в XVIII веке, а затем восстановлен в 2010 году.","choices":["Потешный дворец","Теремной дворец","Дворец в Коломенском","Измайловский дворец"],"answer":2,"steps":["Деревянная резиденция Алексея Михайловича со временем обветшала и была разобрана.","Современное здание в Коломенском воспроизводит её по прежним материалам."],"figure":{"src":"assets/golden-fleece/2016/lessons/5-6-v1/31.webp","alt":"Деревянный дворец с крыльцами и башнями","width":168,"height":148}},{"title":"Царский запрет","question":"В указе Алексея Михайловича 1648 года бесовскими сосудами назывались …","choices":["музыкальные инструменты","иноземные чаши","механические игрушки","аптекарские пузырьки"],"answer":0,"steps":["Скоморохов и их музыку в XVII веке осуждали как нарушение благочестия.","В указах предписывали уничтожать инструменты, называя их «бесовскими сосудами»."]},{"title":"Резная скульптура","question":"В этой местности возникла уникальная для допетровской Руси школа деревянной скульптуры.","choices":["Вологодчина","Кубань","Рязанщина","Верхнекамье"],"answer":3,"steps":["В церквях Верхнего Прикамья сохранились деревянные фигуры святых.","Они образуют особое собрание, известное как пермская деревянная скульптура."],"figure":{"src":"assets/golden-fleece/2016/lessons/5-6-v1/33.webp","alt":"Резное изображение трёх фигур на золочёном фоне","width":417,"height":560,"detailSrc":"assets/golden-fleece/2016/lessons/5-6-v1/33-detail.webp"}},{"title":"Промысел под монастырём","question":"В окрестностях этого монастыря зародился промысел богородской игрушки.","choices":["Троице-Сергиев","Чудов","Псково-Печерский","Ферапонтов"],"answer":0,"steps":["Богородские мастера вырезали из мягкой древесины фигуры животных и людей.","Село находится рядом с Троице-Сергиевой обителью."]},{"title":"Памятный храм","question":"Успенская церковь в Угличе построена в память о …","choices":["защитниках от польских интервентов","произошедшем там диве (чуде)","царевиче Димитрии","митрополите Алексии"],"answer":0,"steps":["В Смутное время земля у угличского Алексеевского монастыря стала местом гибели защитников.","Церковь Успения связана с памятью о погибших."],"figure":{"src":"assets/golden-fleece/2016/lessons/5-6-v1/35.webp","alt":"Белокаменная церковь с шатром","width":167,"height":126}},{"title":"Кто писал ризы","question":"В иконописных артелях XVII века ризы святых писали …","choices":["травщики","знаменщики","златописцы","доличники"],"answer":3,"steps":["В артели лик и руки святого писал личник.","Доличник создавал остальную часть образа, в том числе одежду."]},{"title":"Устройство храма","question":"Этот храм имеет композицию …","choices":["крестово-купольную","корабля","ротонды","ярусную"],"answer":3,"steps":["Сравните части здания снизу вверх.","Каждый следующий объём меньше нижнего, поэтому композиция называется ярусной."],"figure":{"src":"assets/golden-fleece/2016/lessons/5-6-v1/37.webp","alt":"Многоярусный храм с красными стенами","width":172,"height":115}},{"title":"Икона в центре","question":"Эта икона является центром композиции произведения Симона Ушакова «Древо государства Московского».","choices":["Владимирская Богоматерь","Казанская Богоматерь","Киккская Богоматерь","Богоматерь Живоносный источник"],"answer":0,"steps":["На иконе Симона Ушакова вокруг центрального образа растёт дерево с изображениями святых и правителей.","В центре помещён чтимый образ Владимирской Богоматери."],"figure":{"src":"assets/golden-fleece/2016/lessons/5-6-v1/38.webp","alt":"Икона женщины с младенцем","width":118,"height":142}},{"title":"Церковь на Дебре","question":"По преданию, на строительство этой церкви пошли средства, полученные благодаря торговле с Англией.","choices":["Знамения в Дубровицах","Николо-Надеинская в Дербицах","Григория Неокесарийского в Дербицах","Воскресения на Дебре"],"answer":3,"steps":["Легенда связывает постройку костромской церкви с купцом Кириллом Исаковым.","Согласно преданию, среди товаров из Англии ему попалось золото, которое пошло на храм."],"figure":{"src":"assets/golden-fleece/2016/lessons/5-6-v1/39.webp","alt":"Церковь с пятью главами над рекой","width":174,"height":140}},{"title":"Начало царского пира","question":"В первой трети XVII века это блюдо выносилось на царских пирах в первую очередь.","choices":["Студень","Пироги","Жареные птицы","Осетровая икра"],"answer":2,"steps":["Посольские описания пиров упоминают показную подачу крупной жареной птицы.","Так начинали угощение перед последующими блюдами."]},{"title":"Название сборника","question":"«Вертоград многоцветный» Симеона Полоцкого – это сборник …","choices":["стихотворений","басен","сказок","былин"],"answer":0,"steps":["«Вертоград» означает сад.","Симеон Полоцкий собрал в своём «многоцветном саду» стихотворения о разных предметах и событиях."]},{"title":"Подвиг князя Ивана","question":"Князь Иван из «Повести о Еруслане Лазаревиче» …","choices":["убил змия Феодула-царя","вылечил царя Лазаря","отправился в Индию","дал Еруслану в жены Кондурию"],"answer":0,"steps":["В повести сражение со змеем — испытание богатыря.","Князь Иван побеждает змия Феодула-царя."]},{"title":"Как называли спектакли","question":"Первые спектакли придворного театра Алексея Михайловича назывались …","choices":["комедиями","мистериями","трагедиями","игрищами"],"answer":0,"steps":["В придворных документах слово «комедия» могло означать театральное представление вообще.","Например, так именовали постановку на библейский сюжет об Эсфири."]},{"title":"Громкий голос героя","question":"О герое этого произведения сказано, что он своим голосом «всех людей устрашает».","choices":["«Повесть о Горе-Злосчастии»","«Повесть о Фроле Скобееве»","«Повесть о Куре и Лисице»","«Сказание Авраамия Палицына»"],"answer":2,"steps":["Герой повести о Куре и Лисице гордится своим сильным голосом.","Именно петушиное пение помогает понять, почему о нём говорится в условии."]},{"title":"Встреча с Горем","question":"Молодцу из «Повести о Горе-Злосчастии» Горе впервые явилось после того, как он …","choices":["покинул родителей","оказался у реки","предался пьянству","похвастался богатством"],"answer":3,"steps":["Герой повести покидает дом, торгует и начинает хвастаться удачей и богатством.","Горе подступает к нему после этого хвастовства."]},{"title":"Роль отрока Григория","question":"Ксения, героиня «Повести о Тверском Отроче монастыре», называла отрока Григория своим …","choices":["сватом","супругом","суженым","сродником"],"answer":0,"steps":["В повести Григорий помогает князю посвататься к Ксении.","С этим и связано обращение героини «сват»."]},{"title":"Рыба-хвастун","question":"Эта рыба в «Повести о Ерше Ершовиче» сравнивала свою голову с пивным котлом, а хвост с лодейным парусом.","choices":["Осетр","Ерш","Сом","Щука"],"answer":1,"steps":["В пародии на судебную тяжбу мелкий Ёрш преувеличивает свои размеры и силу.","Сравнения с большим котлом и парусом передают его хвастливую речь."]},{"title":"События Азовской осады","question":"В «Повести об Азовском осадном сидении» турки и татары бежали, потому что …","choices":["был убит их паша","им привиделись небесные воины","они были подкуплены","им привиделась Богородица"],"answer":1,"steps":["Автор повести изображает защитников как людей, спасённых небесным заступничеством.","Видение небесных воинов сопровождает отступление осаждавших."]},{"title":"Два героя Маршака","question":"В основе этой сказки С. Маршака лежит произведение смеховой литературы XVII века.","choices":["«Мистер Твистер»","«Сказка про двух лодырей»","«Кошкин дом»","«Вот какой рассеянный»"],"answer":1,"steps":["Смеховая литература описывала лодырей, которые нарочно преувеличивали своё нежелание работать.","Маршак использовал ход такого старого произведения в сказке."]},{"title":"Высшая школа","question":"Первое высшее учебное заведение, открытое в России, – это …","choices":["Славяно-греко-латинская академия","Казанский университет","Киево-Могилянская академия","Смольный институт благородных девиц"],"answer":0,"steps":["Академию основали в Москве братья Лихуды в конце XVII века.","В ней преподавали греческий и латинский языки, риторику и философию."]},{"title":"Сцена на санях","question":"На этой картине В. Суриков изобразил одно из самых драматических событий допетровской Руси XVII века.","choices":["«Боярыня Морозова»","«Покорение Сибири Ермаком»","«Утро стрелецкой казни»","«Переход Суворова через Альпы»"],"answer":0,"steps":["Суриков изобразил, как противницу реформ Никона везут под стражей.","Боярыня Морозова поднимает два пальца, а вокруг саней расходится толпа."],"figure":{"src":"assets/golden-fleece/2016/lessons/5-6-v1/51.webp","alt":"Картина с женщиной на санях в окружении толпы","width":560,"height":288,"detailSrc":"assets/golden-fleece/2016/lessons/5-6-v1/51-detail.webp"}},{"title":"Песня о Разине","question":"А. Пушкин – автор этой песни о Степане Разине.","choices":["«Утес Стеньки Разина»","«Как по Волге-реке, по широкой…»","«Из-за острова на стрежень»","«Сон Степана Разина»"],"answer":1,"steps":["Пушкин создал несколько песен о Разине в подражание устному народному стиху.","Начальная строка о широкой Волге принадлежит этому циклу."]},{"title":"Опера о стрелецком бунте","question":"В основу сюжета этой оперы М. Мусоргского положены события стрелецкого бунта 1682 года.","choices":["«Хованщина»","«Царская невеста»","«Борис Годунов»","«Сорочинская ярмарка»"],"answer":0,"steps":["Мусоргский обратился к противостоянию стрельцов, царевны Софьи и сторонников Петра.","Название «Хованщина» связано с князем Иваном Хованским, руководившим стрельцами."]},{"title":"Опера Кавоса","question":"Первую оперу на сюжет из русской истории XVII века написал …","choices":["И. Маттезон","А. Верстовский","М. Глинка","К. Кавос"],"answer":3,"steps":["Катерино Кавос сочинил оперу «Иван Сусанин», которая шла в 1815 году.","Глинка обратился к тому же герою позднее."]},{"title":"Старая Москва на картинах","question":"Этот художник с археологической точностью изображал в своих произведениях Москву XVII века.","choices":["А. Васнецов","В. Поленов","В. Васнецов","Б. Кустодиев"],"answer":0,"steps":["Аполлинарий Васнецов изучал карты и археологические сведения перед созданием городских пейзажей.","Его картины показывают деревянные улицы и сооружения старой Москвы."],"figure":{"src":"assets/golden-fleece/2016/lessons/5-6-v1/55.webp","alt":"Мужчина в чёрном сюртуке","width":114,"height":136}},{"title":"Сон на Волге","question":"Действие этой комедии А. Островского происходит во второй половине XVII столетия.","choices":["«Тушино»","«Дмитрий Самозванец и Василий Шуйский»","«Воевода (Сон на Волге)»","«Козьма Захарьич Минин, Сухорук»"],"answer":2,"steps":["Действие «Воеводы» Островского происходит в городе на Волге.","Воевода и другие персонажи принадлежат к московской эпохе второй половины XVII века."]},{"title":"Картина об Отрепьеве","question":"За создание картины «Бегство Григория Отрепьева» большой золотой медали Академии художеств был удостоен …","choices":["К. Маковский","В. Суриков","И. Репин","Г. Мясоедов"],"answer":3,"steps":["Григорий Мясоедов обратился к фигуре Григория Отрепьева, которого связывают с Лжедмитрием I.","Полотно показывает значимых для Смуты персонажей."],"figure":{"src":"assets/golden-fleece/2016/lessons/5-6-v1/57.webp","alt":"Картина с людьми за столом в полутёмной комнате","width":560,"height":354,"detailSrc":"assets/golden-fleece/2016/lessons/5-6-v1/57-detail.webp"}},{"title":"Храм по старым образцам","question":"При проектировании этого храма Александр III рекомендовал ориентироваться на московскую и ярославскую архитектуру XVII века.","choices":["Исаакиевский собор","Спас на Крови","Храм Христа Спасителя","Николаевский морской собор"],"answer":1,"steps":["Александр III хотел, чтобы храм на месте гибели Александра II напоминал древнерусское зодчество.","Спас на Крови узнаётся по пёстрым главам и богатому декору."]},{"title":"Источник оперного сюжета","question":"Это произведение стало одним из источников либретто оперы Н. Римского-Корсакова «Сказание о невидимом граде Китеже и деве Февронии».","choices":["«Повесть о Горе-Злосчастии»","«Повесть о Савве Грудцыне»","«Житие протопопа Аввакума»","«Сказание Авраамия Палицына»"],"answer":0,"steps":["Либретто «Сказания о невидимом граде Китеже» соединяет разные старинные предания и повести.","Мотивы нравственного испытания и страдания нашли в «Повести о Горе-Злосчастии»."]},{"title":"Монастырские фасады","question":"В этом петербургском монастыре в XIX веке были построены здания в характере русского узорчатого зодчества XVII века.","choices":["Троице-Сергиева пустынь","Смольный монастырь","Воскресенский Новодевичий монастырь","Александро-Невская лавра"],"answer":0,"steps":["В Троице-Сергиевой пустыни под Петербургом есть здания XIX века в русском стиле.","Башенки, наличники и узорчатая кладка напоминают архитектуру XVII века."],"figure":{"src":"assets/golden-fleece/2016/lessons/5-6-v1/60.webp","alt":"Краснокирпичный фасад с высокой двускатной крышей","width":128,"height":165}}]);
